for _, row in ipairs(rows) do
    for i, code in ipairs(codes) do
        local t = GT.locales[code]
        if type(t) ~= "table" then t = {}; GT.locales[code] = t end
        if t[row[1]] == nil then t[row[1]] = row[i + 1] end
    end
end
